    sell_book = []  # list of (price, arrival_time, id, qty) for resting sell orders
    order_map = {}  # id -> (side, qty_remaining, arrival_time) for resting orders
    arrival_time = 0

    for order in orders:
        arrival_time += 1
        order_type = order[0]

        if order_type == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, _, _ = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                else:
                    sell_book = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]

